  1→/**
  2→ * File-based session persistence for thos agents.
  3→ *
  4→ * Persists agent state + message history to JSON files in
  5→ * `.thos/sessions/<agentId>.json` so data survives server restarts.
  6→ *
  7→ * Uses debounced writes (150ms) for high-frequency events (streaming) and
  8→ * synchronous writes for critical state changes (spawn, result, status).
  9→ */
 10→
 11→import { mkdirSync, writeFileSync, readFileSync, readdirSync, unlinkSync, existsSync } from "fs";
 12→import { join } from "path";
 13→import type { AgentStatus, ServerMessage } from "../lib/types";
 14→
 15→const SESSION_DIR = join(process.cwd(), ".thos", "sessions");
 16→
 17→/** Shape of a persisted agent on disk. */
 18→export interface PersistedAgent {
 19→  id: string;
 20→  state: {
 21→    agentId: string;
 22→    status: AgentStatus;
 23→    tmuxSession: string | null;
 24→    label: string;
 25→    createdAt: number;
 26→    sessionId: string | null;
 27→  };
 28→  messageHistory: ServerMessage[];
 29→}
 30→
 31→export class SessionStore {
 32→  private dir: string;
 33→  private debounceTimers = new Map<string, ReturnType<typeof setTimeout>>();
 34→
 35→  constructor(dir: string = SESSION_DIR) {
 36→    this.dir = dir;
 37→    mkdirSync(this.dir, { recursive: true });
 38→  }
 39→
 40→  /** File path for a given agent ID. */
 41→  private filePath(agentId: string): string {
 42→    return join(this.dir, `${agentId}.json`);
 43→  }
 44→
 45→  /** Debounced write — batches rapid stream events (150ms). */
 46→  save(agent: PersistedAgent): void {
 47→    const existing = this.debounceTimers.get(agent.id);
 48→    if (existing) clearTimeout(existing);
 49→    this.debounceTimers.set(
 50→      agent.id,
 51→      setTimeout(() => {
 52→        this.debounceTimers.delete(agent.id);
 53→        this.writeFile(agent);
 54→      }, 150)
 55→    );
 56→  }
 57→
 58→  /** Immediate write — use for critical state changes (spawn, result, status). */
 59→  saveSync(agent: PersistedAgent): void {
 60→    // Cancel any pending debounced write
 61→    const existing = this.debounceTimers.get(agent.id);
 62→    if (existing) {
 63→      clearTimeout(existing);
 64→      this.debounceTimers.delete(agent.id);
 65→    }
 66→    this.writeFile(agent);
 67→  }
 68→
 69→  /** Load a single agent from disk. Returns null if not found. */
 70→  load(agentId: string): PersistedAgent | null {
 71→    const fp = this.filePath(agentId);
 72→    if (!existsSync(fp)) return null;
 73→    try {
 74→      const raw = readFileSync(fp, "utf-8");
 75→      return JSON.parse(raw) as PersistedAgent;
 76→    } catch (err) {
 77→      console.error(`[session-store] failed to load ${agentId}:`, err);
 78→      return null;
 79→    }
 80→  }
 81→
 82→  /** Load all persisted agents on server startup. */
 83→  loadAll(): PersistedAgent[] {
 84→    try {
 85→      const files = readdirSync(this.dir).filter((f) => f.endsWith(".json"));
 86→      const agents: PersistedAgent[] = [];
 87→      for (const file of files) {
 88→        try {
 89→          const raw = readFileSync(join(this.dir, file), "utf-8");
 90→          agents.push(JSON.parse(raw) as PersistedAgent);
 91→        } catch (err) {
 92→          console.error(`[session-store] failed to parse ${file}:`, err);
 93→        }
 94→      }
 95→      return agents;
 96→    } catch {
 97→      return [];
 98→    }
 99→  }
100→
101→  /** Delete an agent's persisted file. */
102→  remove(agentId: string): void {
103→    const fp = this.filePath(agentId);
104→    try {
105→      if (existsSync(fp)) unlinkSync(fp);
106→    } catch (err) {
107→      console.error(`[session-store] failed to remove ${agentId}:`, err);
108→    }
109→    // Also cancel any pending debounced write
110→    const existing = this.debounceTimers.get(agentId);
111→    if (existing) {
112→      clearTimeout(existing);
113→      this.debounceTimers.delete(agentId);
114→    }
115→  }
116→
117→  /** Flush all pending debounced writes synchronously (for graceful shutdown). */
118→  flushAll(allAgents: PersistedAgent[]): void {
119→    // Cancel all pending timers
120→    for (const [id, timer] of this.debounceTimers) {
121→      clearTimeout(timer);
122→      this.debounceTimers.delete(id);
123→    }
124→    // Write all agents
125→    for (const agent of allAgents) {
126→      this.writeFile(agent);
127→    }
128→  }
129→
130→  private writeFile(agent: PersistedAgent): void {
131→    try {
132→      writeFileSync(this.filePath(agent.id), JSON.stringify(agent, null, 2));
133→    } catch (err) {
134→      console.error(`[session-store] failed to write ${agent.id}:`, err);
135→    }
136→  }
137→}
